cat > /app/hierarchical_model.stan << 'EOF'
// Hierarchical Beta-Binomial model
// y_i ~ Binomial(n_i, theta_i)
// theta_i ~ Beta(alpha, beta)
// prior: p(alpha, beta) proportional to (alpha + beta)^(-5/2)
data {
  int<lower=1> N;                // number of groups
  array[N] int<lower=0> y;       // number of successes
  array[N] int<lower=1> n;       // number of trials
}
parameters {
  real<lower=0> alpha;           // beta shape parameter 1
  real<lower=0> beta;            // beta shape parameter 2
  vector<lower=0, upper=1>[N] theta;  // group success probabilities
}
model {
  y ~ binomial(n, theta);
  theta ~ beta(alpha, beta);
  target += -2.5 * log(alpha + beta);   // (alpha + beta)^(-5/2) prior
}
EOF
echo "stan file written"; cat /app/hierarchical_model.stan

